package com.tecsup.minishop.repository;
import com.tecsup.minishop.model.Product; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class ProductRepositoryIntegrationTest { @Autowired ProductRepository productRepository; @BeforeEach void setUp(){productRepository.deleteAll();} @Test @DisplayName("Guarda producto y asigna ID") void shouldSaveProductAndAssignId(){Product p=productRepository.save(Product.builder().name("Laptop Lenovo").price(2500.0).stock(10).build()); assertThat(p.getId()).isNotNull(); assertThat(productRepository.findById(p.getId())).isPresent();} @Test @DisplayName("Encuentra producto por ID") void shouldFindProductById(){Product p=productRepository.save(Product.builder().name("Mouse Logitech").price(85.0).stock(50).build()); assertThat(productRepository.findById(p.getId())).get().extracting(Product::getName).isEqualTo("Mouse Logitech");} @Test @DisplayName("Retorna vacío si ID no existe") void shouldReturnEmptyWhenIdNotFound(){Optional<Product> found=productRepository.findById(999L); assertThat(found).isEmpty();} @Test @DisplayName("Busca por nombre ignorando mayúsculas") void shouldFindProductsByNameIgnoringCase(){productRepository.save(Product.builder().name("Teclado Mecánico").price(150.0).stock(20).build()); productRepository.save(Product.builder().name("Teclado Membrana").price(45.0).stock(30).build()); productRepository.save(Product.builder().name("Mouse").price(20.0).stock(3).build()); assertThat(productRepository.findByNameContainingIgnoreCase("TECLADO")).hasSize(2);}}
